function drawSceneExtent(){
 line(boundary.map(p=>project(...p,1)),'#f0efd7a0',1,[5,5]);
 if(referenceRings)for(const b of BASES){const pts=Array.from({length:97},(_,i)=>project(b.x+SCENE.radius*Math.cos(i*Math.PI/48),b.y+SCENE.radius*Math.sin(i*Math.PI/48),1));line(pts,b.color+'99',1.2,[7,5]);const p=project(b.x,b.y-SCENE.radius,2);label(b.name+' · 400 m',p.x,p.y-7,b.color,10,true);}
 if(sim.config.boundaryFlow)for(const r of OPEN_ROUTES){for(const [point,text,color]of [[r.entry,'入口','#a3edc3'],[r.exit,'出口','#f0c998']]){const p=project(...point,2);ctx.fillStyle=color;ctx.beginPath();ctx.arc(p.x,p.y,4,0,Math.PI*2);ctx.fill();label(text,p.x,p.y-10,color,9,true);}}
}
function colorLink(u,p,q,selectedLink){const color=u.blocked?'#f5bd6b':BASES[u.cell].color;line([p,q],color+(selectedLink?'ce':'1a'),selectedLink?1.6:.8,u.blocked?[5,5]:[]);if(selectedLink){const f=(sim.time*2)%1,a=sim.config.direction==='DL'?q:p,b=sim.config.direction==='DL'?p:q;ctx.fillStyle=color;ctx.beginPath();ctx.arc(a.x+(b.x-a.x)*f,a.y+(b.y-a.y)*f,3,0,Math.PI*2);ctx.fill();}}
function draw(){if(navigation)navigation.render();else drawCampus();}
function resize(){const r=canvas.parentElement.getBoundingClientRect();W=r.width;H=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);draw();}
function sparkline(u){const c=$('sparkline'),r=c.getBoundingClientRect();if(!r.width)return;c.width=r.width*dpr;c.height=66*dpr;const g=c.getContext('2d');g.scale(dpr,dpr);const max=Math.max(...u.history,1),points=u.history.map((v,i)=>({x:r.width*i/29,y:57-v/max*46}));g.strokeStyle='#294150';g.lineWidth=.6;for(const y of [12,34,57]){g.beginPath();g.moveTo(0,y);g.lineTo(r.width,y);g.stroke();}if(points.length){g.beginPath();g.moveTo(0,64);points.forEach(p=>g.lineTo(p.x,p.y));g.lineTo(points.at(-1).x,64);g.closePath();const gradient=g.createLinearGradient(0,0,0,66);gradient.addColorStop(0,'#64e4b144');gradient.addColorStop(1,'#64e4b100');g.fillStyle=gradient;g.fill();g.beginPath();points.forEach((p,i)=>i?g.lineTo(p.x,p.y):g.moveTo(p.x,p.y));g.strokeStyle='#64e4b1';g.lineWidth=1.7;g.stroke();}}
let lastEventKey='';
function render(){const u=sim.users[selected],dl=sim.config.direction==='DL';$('onlineCount').textContent=sim.activeUsers.length;$('buildingCount').textContent=BUILDINGS.length;$('flowCounts').textContent='累计进入 '+sim.flow.entered+' · 离开 '+sim.flow.exited;$('flowEvents').innerHTML=sim.flow.events.slice(0,3).map(e=>`<div>${timeText(e.time)} · ${e.id} ${e.title}</div>`).join('')||(sim.config.boundaryFlow?'开放道路连接场外，等待下一次进出。':'闭合路线模式，终端不进出场景。');$('deviceStatus').textContent=u.active?'场内在线':u.phase==='approaching'?'场外接近':'已离场';$('locateUE').disabled=!u.active;for(const item of sim.users){const option=$('ueSelect').options[item.id];const text=item.name+' · '+(!item.active?(item.phase==='approaching'?'待进入':'已离场'):item.environment==='indoor'?'室内'+(item.speed?'移动':'静止'):item.transit?'过境移动':'室外');if(option.textContent!==text)option.textContent=text;}$('clock').textContent=timeText(sim.time);$('runState').textContent=running?'仿真运行中':'仿真已暂停';$('play').textContent=running?'Ⅱ 暂停':'▶ 继续';$('timeProgress').style.width=`${sim.time%60/60*100}%`;$('ueType').textContent=u.type;$('ueLocation').textContent=u.environment==='indoor'?BUILDINGS[u.building].name+' · '+u.floor+'F · 高度 '+u.z.toFixed(1)+' m':'室外 · 高度 '+u.z.toFixed(1)+' m';$('indoorStatus').hidden=!(indoorView&&u.environment==='indoor');$('indoorStatus').textContent=u.environment==='indoor'?BUILDINGS[u.building].name+' · '+u.floor+'F 透视 · ◆ 室内终端':'';$('cellName').textContent=u.active?BASES[u.cell].name:'场外 · 未调度';$('cellDot').style.background=BASES[u.cell].color;$('losStatus').textContent=!u.active?'不参与场内仿真':u.penetrationLoss>0?'室内穿透 '+u.penetrationLoss.toFixed(1)+' dB':u.blocked?'建筑遮挡 NLOS':'视距 LOS';$('losStatus').style.color=u.blocked?'#f5bd6b':'#9ebfae';$('sinr').textContent=u.active?u.sinr.toFixed(1):'—';$('cqi').textContent=u.active?`${u.cqi} / ${u.mcs}`:'—';$('ueRate').textContent=u.active?u.rate.toFixed(2):'0.00';$('latency').textContent=u.active?u.latency.toFixed(1):'—';$('queue').textContent=(u.queue/8000).toFixed(1);$('prbs').textContent=u.prbs;$('retrans').textContent=u.active?u.retrans.toFixed(1)+'%':'—';$('queueLabel').textContent=dl?'基站发送队列':'终端发送队列';$('totalRate').textContent=sim.stats.rate.toFixed(1);$('util').textContent=sim.stats.util.toFixed(1);$('avgDelay').textContent=sim.stats.latency.toFixed(1);$('totalRetrans').textContent=sim.stats.retrans.toFixed(1);$('harqProcesses').innerHTML=u.pending.map((p,i)=>`<span class="${p?(p.due===null?'retry':'wait'):''}" title="进程 ${i} · ${p?(p.due===null?'待重传':'等待反馈'):'空闲'}">${i}</span>`).join('');
$('directionTag').textContent=dl?'DOWNLINK':'UPLINK';$('macFlow').innerHTML=!u.active?'<div class="flow-node"><b>终端当前在场外</b><span>未分配 PRB；进入场景后建立场内链路</span></div>':dl?`<div class="flow-node"><b>gNB MAC · 发送</b><span>队列 → 调度 → MAC PDU</span></div><span class="flow-arrow">⇄</span><div class="flow-node phy"><b>PHY / 无线信道</b><span>SINR ${u.sinr.toFixed(1)} dB · HARQ</span></div><span class="flow-arrow">⇄</span><div class="flow-node"><b>UE MAC · 接收</b><span>解复用 · ACK / NACK</span></div>`:`<div class="flow-node"><b>UE MAC · 发送</b><span>BSR → 授权 → MAC PDU</span></div><span class="flow-arrow">⇄</span><div class="flow-node phy"><b>PHY / 无线信道</b><span>SINR ${u.sinr.toFixed(1)} dB · HARQ</span></div><span class="flow-arrow">⇄</span><div class="flow-node"><b>gNB MAC · 接收</b><span>调度授权 · ACK / NACK</span></div>`;
$('resourceTitle').textContent=u.active?BASES[u.cell].name+' · 最近时隙的频域资源':'场外终端 · 无场内资源';$('resourceGrid').innerHTML=(u.active?sim.trace[u.cell]:[]).map(col=>`<div class="resource-col">${col.map(id=>`<div class="resource-cell ${id===selected?'selected':id>=0?'other':''}" title="${id<0?'空闲':sim.users[id].name} · 3 PRB"></div>`).join('')}</div>`).join('');
const key=u.name+':'+selected+':'+u.events.map(e=>e.time+e.title).join(',');if(lastEventKey!==key){$('events').innerHTML=u.events.slice(0,12).map(e=>`<div class="event ${e.retry?'retry':''}"><time>${timeText(e.time)}</time><div><b>${e.title}</b><span>${e.detail}</span></div></div>`).join('');lastEventKey=key;}sparkline(u);draw();}
function selectUE(id){if(!Number.isInteger(id)||id<0||id>=12)throw Error('终端编号必须在 0–11 之间');selected=id;$('ueSelect').value=String(id);render();return sim.snapshot().users[id];}
function reset(){sim.reset();heatDirty=true;render();}
function scenario(value){if(!['campus','shadow','hotspot','indoor'].includes(value))throw Error('未知场景');sim.config.scenario=value;$('scenario').value=value;const preset={indoor:{load:100,note:'4 个室内终端分布于办公楼与厂房，包含移动和静止业务。',hint:'选择 UE-09～12，点击「定位终端」查看楼层透视与室内路线。'},campus:{load:100,note:'开放道路车流进出场景，室内与常驻终端持续在线。',hint:'观察入口、出口和在线数量；可加速至 5× 查看进出过程。'},shadow:{load:100,note:'终端集中在厂房边缘，观察建筑遮挡对无线传输的影响。',hint:'关闭「建筑遮挡损耗」，对比同一位置的信道与 MAC 表现。'},hotspot:{load:200,note:'办公区终端集中且业务增加，观察队列积压与调度公平性。',hint:'切换 PF、轮询与最大信道质量，观察不同终端能获得多少资源。'}}[value];sim.config.load=preset.load;sim.config.blockage=true;$('load').value=preset.load;$('loadValue').textContent=preset.load+'%';$('blockage').checked=true;$('scenarioNote').textContent=preset.note;$('experimentHint').textContent=preset.hint;reset();if(value==='indoor'){selectUE(8);navigation.focusAt(sim.users[8].x,sim.users[8].y);}}
$('boundaryFlow').onchange=e=>{sim.config.boundaryFlow=e.target.checked;reset();};$('referenceRings').onchange=e=>{referenceRings=e.target.checked;draw();};
$('locateUE').onclick=()=>{const u=sim.users[selected];if(!u.active)return;navigation.focusAt(u.x,u.y);};$('indoorView').onchange=e=>{indoorView=e.target.checked;render();};
$('scenario').onchange=e=>scenario(e.target.value);$('scheduler').onchange=e=>{sim.config.scheduler=e.target.value;for(const u of sim.users)sim.log(u,'调度策略更新',e.target.value);render();};$('ueSelect').onchange=e=>selectUE(Number(e.target.value));$('load').oninput=e=>{sim.config.load=Number(e.target.value);$('loadValue').textContent=e.target.value+'%';render();};$('power').oninput=e=>{sim.config.power=Number(e.target.value);$('powerValue').textContent=e.target.value+' dBm';sim.updateChannels();heatDirty=true;render();};$('blockage').onchange=e=>{sim.config.blockage=e.target.checked;sim.updateChannels();heatDirty=true;render();};$('mobility').onchange=e=>sim.config.mobility=e.target.checked;$('heatmap').onchange=e=>{heatmap=e.target.checked;draw();};$('links').onchange=e=>{links=e.target.checked;draw();};$('play').onclick=()=>{running=!running;render();};$('step').onclick=()=>{running=false;sim.step();render();};$('speed').onchange=e=>speed=Number(e.target.value);$('reset').onclick=reset;document.querySelectorAll('[data-dir]').forEach(b=>b.onclick=()=>{if(b.dataset.dir===sim.config.direction)return;sim.config.direction=b.dataset.dir;document.querySelectorAll('[data-dir]').forEach(x=>x.classList.toggle('active',x===b));reset();});navigation=new AirViewGlobe.GlobeNavigation({canvas,dimensions:()=>({width:W,height:H,dpr}),angle:()=>angle,setAngle:value=>angle=value,visuals:realistic,drawCampus:(scale,tilt,viewAngle,focus)=>{sceneFocus=focus;zoom=scale;sceneTilt=tilt;const savedAngle=angle;angle=viewAngle;try{drawCampus();}finally{angle=savedAngle;}},clearCampus:()=>{realistic.campusActive=false;ctx.clearRect(0,0,W,H);hitTargets=[];},selectAt:(x,y)=>{const nearest=hitTargets.map(t=>({...t,d:Math.hypot(t.x-x,t.y-y)})).sort((a,b)=>a.d-b.d)[0];if(nearest&&nearest.d<28)selectUE(nearest.id);}});
new ResizeObserver(resize).observe(canvas.parentElement);resize();render();setInterval(()=>{if(running){sim.step(200*speed);render();}},100);
window.airview={getState:()=>({...sim.snapshot(),selectedUE:sim.users[selected].name,running,navigation:navigation.state(),visuals:{renderer:realistic.ready?'webgl':'canvas-fallback',earthTexture:realistic.earthReady,imageryMonth:'2004-05',indoorView,referenceRings,heatmap,links}}),selectUE,setScenario:scenario,setRunning:value=>{if(typeof value!=='boolean')throw Error('running 必须为布尔值');running=value;render();return{running};}};
const mc=document.modelContext;if(mc?.registerTool){const tools=[{name:'navigate_twin_view',description:'在地球、上海区域、上海城市及园区之间平滑切换视角，不改变 MAC 仿真状态',inputSchema:{type:'object',properties:{view:{type:'string',enum:['earth','region','city','campus']}},required:['view'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||!['earth','region','city','campus'].includes(input.view)||Object.keys(input).length!==1)throw Error('无效视图');navigation.fly(input.view);return {navigation:navigation.state(),action:'camera_flight_started'};}},{name:'read_twin_state',description:'读取仿真时间、配置、终端链路与 MAC 指标',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>window.airview.getState()},{name:'configure_twin_scene',description:'切换场景并重置仿真；可选择终端并暂停或继续',inputSchema:{type:'object',properties:{scenario:{type:'string',enum:['campus','shadow','hotspot','indoor']},terminal:{type:'integer',minimum:0,maximum:11},running:{type:'boolean'}},additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['scenario','terminal','running'].includes(k)))throw Error('无效参数');if(input.scenario!==undefined&&!['campus','shadow','hotspot','indoor'].includes(input.scenario))throw Error('未知场景');if(input.terminal!==undefined&&(!Number.isInteger(input.terminal)||input.terminal<0||input.terminal>11))throw Error('无效终端');if(input.running!==undefined&&typeof input.running!=='boolean')throw Error('无效运行状态');if(input.scenario!==undefined)scenario(input.scenario);if(input.terminal!==undefined)selectUE(input.terminal);if(input.running!==undefined)window.airview.setRunning(input.running);return window.airview.getState();}}];for(const tool of tools){try{Promise.resolve(mc.registerTool(tool)).catch(()=>{});}catch{}}}
